def mutation_distance(t1, t2):
    s1 = set(t1.axioms.keys())
    s2 = set(t2.axioms.keys())
    return len(s1.symmetric_difference(s2))

def closure(universe, S):
    th = {p for p in all_preds if all(p(x) for x in S)}
    return {x for x in universe if all(p(x) for p in th)}

def shortest_path(t1, t2):
    path = []
    for a in t1.axioms - t2.axioms: path.append(('remove', a))
    for a in t2.axioms - t1.axioms: path.append(('add', a))
    return path
